            font-size: 24px;
            font-weight: bold;
            color: var(--border-color);
        }

        .trending-title {
            font-size: 15px;
            font-weight: 500;
        }

        .news-grid {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 20px;
            margin-top: 30px;
            margin-bottom: 50px;
        }

        .news-card {
            background-color: var(--white);
            border: 1px solid var(--border-color);
            transition: transform 0.2s;
        }

        .news-card:hover {
            transform: translateY(-5px);
            box-shadow: 0 10px 15px -3px rgba(0,0,0,0.1);
        }

        .card-img {
            width: 100%;
            height: 180px;
            background-color: #ddd;
            object-fit: cover;
        }

        .card-content {
            padding: 15px;
        }

        .card-content h2 {
            font-size: 18px;
            margin: 0 0 10px 0;
            line-height: 1.4;
        }

        .card-meta {
            font-size: 13px;
            color: var(--text-gray);
        }

        footer {
            background-color: var(--primary-color);
            color: white;
            padding: 40px 0;
            margin-top: 50px;
        }

        .footer-grid {
            display: grid;
            grid-template-columns: repeat(4, 1fr);
            gap: 30px;
        }

        .footer-col h4 {
            margin-bottom: 20px;
            font-size: 18px;
        }

        .footer-col ul {
            list-style: none;
            padding: 0;
        }

        .footer-col li {
            margin-bottom: 10px;
            font-size: 14px;
            opacity: 0.8;
        }

